import json,pathlib,html,re,csv
from content import SUMMARIES,SYNTHESIS,PREHISTORY,DOMAINS,NIST_GROUPS
R=pathlib.Path(__file__).resolve().parents[1];S=R/'site';records=json.loads((R/'data/records.json').read_text());by={x['id']:x for x in records}
def e(s):return html.escape(str(s),quote=True)
def paras(s):return ''.join('<p>'+e(t)+'</p>' for t in s.split('|'))
def cite(refs):return '<p class="citations">Sources: '+ ' · '.join(f'<a href="#doc-{id}">{e(by[id]["title"])} — {e(loc)}</a>' for id,loc in refs if id in by)+'</p>'
def date(x):
 p=x.get('date_precision','')
 return ('FY '+x['id'][2:4]+' · date unresolved') if p.startswith('fiscal year') else x['date'][:7] if p.startswith('month') else x['date']
def links(x):
 a=f'<a href="{e(x["url"])}">Official source</a>'
 if x.get('local'):a+=f' · <a href="{e(x["local"])}" download>Original download</a> · <a href="{e(x["extracted"])}">Extracted text</a>'
 if x.get('evidence_id') in by:a+=f' · <a href="#doc-{x["evidence_id"]}">Supporting record</a>'
 return a
nav=[('synthesis','Executive synthesis'),('chronology','Chronology'),('predecessors','Before A-130'),('revisions','A-130 revisions'),('authority','Authority by domain'),('nist','NIST relationships'),('memoranda','Memoranda'),('library','Source library'),('method','Method & limits')]
parts=['''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="A primary-source history of OMB Circular A-130, federal security law, NIST standards and cloud policy."><title>A-130 · History & authority</title><link rel="stylesheet" href="styles.css"><script src="app.js" defer></script></head><body><a class="skip" href="#main">Skip to report</a><aside class="rail"><a class="wordmark" href="#top">A–130<span>History & authority</span></a><nav aria-label="Report sections">''']
parts+=[''.join(f'<a href="#{id}">{title}</a>' for id,title in nav),'<div class="rail-foot">Research edition<br>10 October 2026<br><a href="manifest.json" download>Source manifest ↓</a><br><a href="https://github.com/pete-wai/fedramp-a130">GitHub repository</a></div></nav></aside><main id="main"><header id="top"><h1>Where federal information security gets its authority.</h1><p class="deck">A history of OMB Circular A-130, the laws behind it, and the NIST standards that developed alongside it.</p><p class="edition">1965–2026 · Primary-source research · Independent report</p><a class="button" href="#synthesis">Read the findings</a> <a class="text-action" href="#library">Explore the documents →</a></header>']
parts += ['<section id="synthesis"><h2>A central framework. Several sources of authority.</h2><div class="prose">',paras(SYNTHESIS),cite([('a130-2016','§§3, 5, 6, 9'),('fisma2002','§§303–304'),('fisma2014','§2'),('m-24-15','Scope and responsibilities')]),'</div><div class="chain" aria-label="Complementary responsibilities"><div><b>Congress</b><span>Assigns duties and authority</span></div><div><b>OMB & agencies</b><span>Policy, oversight, implementation</span></div><div><b>NIST & Commerce</b><span>Technical work and standards</span></div></div><p class="note">Read the arrows with care: this report distinguishes explicit mandates, explicit OMB direction, implementation support, later incorporation, separate executive direction and chronological association. Publication order alone establishes none of them.</p></section>']
parts += ['<section id="chronology"><h2>Three streams, one chronology.</h2><p class="intro">Read across a period to compare laws, OMB actions and technical publications. Select an event for its evidence record. Lanes show timing, not inferred causation.</p><div class="timeline-scroll" tabindex="0" role="region" aria-label="Chronology table"><table class="timeline"><thead><tr><th scope="col">Period</th><th scope="col">Law & executive direction</th><th scope="col">OMB policy</th><th scope="col">NIST / NBS</th></tr></thead><tbody>']
selected=['a71-1965','brooks','privacy','fips31','fips46','a71-1978','fips65','pra1980','sp50085','a130-1985','csa','bulletin88','bulletin90','a130-1993','a130-1994-fr','fips1401','pra1995','sp80012','clinger','a130-1996','sp80018','a130-2000','gpea-guidance','gisra','fips197','fips1402','fisma2002','fips199','sp80037','sp80053','fips200','hspd12','sp80063v101','sp800371','eo13556','fedramp2011','sp800145','sp800144','sp800534','fisma2014','sp800171','a130-2016','sp800372','fips1403','sp800535','sp800207','eo14028','sp800218','m-22-09','fedramp-act','quantumact','sp8001713','fips203','m-24-15','sp800634','m-26-15']
for lo,hi in [(1965,1979),(1980,1989),(1990,1995),(1996,2000),(2001,2006),(2007,2014),(2015,2020),(2021,2026)]:
 cells=[[],[],[]]
 for id in sorted(selected,key=lambda id:by.get(id,{"date":"9999"})["date"]):
  if id not in by:continue
  x=by[id];y=int(x['date'][:4])
  if lo<=y<=hi:
   lane=0 if x['type'] in ['Law','Executive directive'] else 2 if x['type']=='NIST' else 1
   cells[lane].append(f'<button class="event" data-document="{id}"><span>{e(date(x))}</span>{e(x["title"])}</button>')
 parts+=['<tr><th scope="row">'+str(lo)+'–'+str(hi)+'</th>'+''.join('<td>'+''.join(c)+'</td>' for c in cells)+'</tr>']
parts+=['</tbody></table></div><div id="event-detail" class="event-detail" tabindex="-1" aria-live="polite"><p>Select an event to see its source, scope and relationship.</p></div></section>']
parts+=['<section id="predecessors"><h2>Before the circular.</h2><div class="prose">',paras(PREHISTORY),cite([('fips12','§4.6'),('brooks','§111(f)'),('privacy','§3'),('a130-1996-preamble','Supplementary information'),('sp50085','Abstract; question 6')]),'</div></section><section id="revisions"><h2>Six substantive milestones.</h2><p class="intro">Each account separates what changed from the laws and technical work surrounding it. Earlier proposals and later consolidation are identified within the summaries.</p>']
for id,title,body,refs in SUMMARIES:parts += [f'<article class="revision" id="revision-{id}"><h3>{e(title)}</h3><p class="edition">{e(by[id]["locator"])}</p><div class="prose">',paras(body),cite(refs),f'<p>{links(by[id])}</p></div></article>']
parts+=['</section><section id="authority"><h2>How much runs through A-130?</h2><p class="intro">A qualitative assessment by domain is more defensible than a percentage. A document count would confuse technical detail with legal force.</p>']
for title,role,body,id,loc in DOMAINS:parts += [f'<article class="domain"><h3>{e(title)}</h3><p class="finding">{e(role)}</p><p>{e(body)}</p>',cite([(id,loc)]),'</article>']
parts+=['<div class="prose"><h3>Who directs, who develops, who promulgates?</h3><p>OMB’s policy and oversight role, NIST’s technical responsibilities and Commerce’s standards-promulgation role are not interchangeable. FISMA imposes obligations on agency heads directly. A Special Publication is not automatically a mandatory rule merely because NIST published it: determine whether a statute, FIPS, OMB policy, regulation or contract makes its provisions applicable, and distinguish mandatory language from recommendations.</p><p>The national-security exception is a genuine boundary. A separate affirmative NIST assignment is something different: it shows that Congress did not make the existence of a NIST program depend on an A-130 revision. It does not establish that OMB lacks authority over agencies’ use of that work.</p>',cite([('fisma2002','§§301, 303–304'),('fisma2014','§2, 44 USC 3553–3554 and 3557'),('a130-2016','§§3, 6 and 9')]),'</div></section><section id="nist"><h2>NIST’s work: mandate, method and adoption.</h2>']
for title,body,refs in NIST_GROUPS:parts += [f'<article class="prose"><h3>{e(title)}</h3><p>{e(body)}</p>',cite(refs),'</article>']
parts+=['</section><section id="memoranda"><h2>The policy between revisions.</h2><div class="prose"><p>Memoranda can implement a statute, extend A-130, apply its existing requirements to a new domain, or later be incorporated into the circular. The library includes direct A-130 references found in the archive scan and selected policy extensions, including documents whose extracted text has no literal A-130 match.</p><p>Some relationships are especially clear: M-95-22 was incorporated in the 1996 explanatory appendix; M-00-07 and the GPEA guidance were incorporated in 2000; M-04-04 explicitly tasked NIST on electronic authentication. The unnumbered December 8, 2011 FedRAMP memorandum is a separate record, later rescinded by M-24-15. Annual FISMA reporting instructions implement a recurring statutory/policy program; their deadlines should not be treated as permanently current.</p>',cite([('a130-1996-preamble','Appendix IV discussion'),('a130-2000-notice','Incorporation discussion'),('m-04-04','NIST guidance assignment'),('fedramp2011','Introduction'),('m-24-15','Rescission')]),'<p>Rescission is recorded where the successor document supports it. M-17-26 contains both eliminations and narrower modifications; M-19-17 expressly rescinds several identity memoranda. M-25-21 and M-25-22 replace the preceding AI memoranda. A default “historical inventory” label means that continued applicability has not been established, not that the document is still in force.</p>',cite([('m-17-26','Eliminated, modified and paused sections'),('m-19-17','p. 13'),('m-25-21','p. 1'),('m-25-22','p. 1')]),'</div><button class="button" id="show-memos">Show memorandum inventory</button></section>']
parts+=['<section id="library"><h2>Read the evidence.</h2><p class="intro">Search titles, relevance notes and extracted passages. Filters combine. Original files retain their government-source provenance; text files are reading aids. Dates marked by month or fiscal year do not assert a precise issuance day.</p><form id="filters" class="filters" role="search"><label class="search-label">Search documents<input id="query" type="search" placeholder="Try cloud, authorization, or M-04-04"></label>']
for id,label,values in [('type','Document type',sorted(set(x['type'] for x in records))),('era','Era',['Before 1985','1985–1999','2000–2015','2016–2026']),('relation','Relationship',sorted(set(x['relation'] for x in records))),('term','Term flag',['cloud','commercial services','FedRAMP','related terminology']),('sort','Sort',['Oldest first','Newest first','Title A–Z'])]:
 parts+=[f'<label>{label}<select id="{id}">'+('' if id=='sort' else '<option value="">All</option>')+''.join(f'<option>{e(v)}</option>' for v in values)+'</select></label>']
parts+=['<button type="reset">Reset filters</button></form><p id="result-count" role="status">'+str(len(records))+' documents</p><p id="empty" hidden>No documents match. Clear a filter or try a broader search.</p><div id="records">']
for x in records:
 era='Before 1985' if x['date']<'1985' else '1985–1999' if x['date']<'2000' else '2000–2015' if x['date']<'2016' else '2016–2026'
 matches=x.get('matches',[]);tags='|'.join(m['term'] for m in matches)
 body=f'<div class="record-heading"><p class="record-date">{e(date(x))}<span>{e(x["type"])}</span></p><h3><a href="#doc-{x["id"]}">{e(x["title"])}</a></h3></div><p class="record-relation">{e(x["relation"])} · {e(x["availability"])}</p><p>{e(x.get("note", ""))}</p><p class="locator">{e(x["locator"])}</p><p class="status">{e(x["status"])}</p><p class="source-links">{links(x)}</p>'
 if x.get('reference_passage'): body+='<details><summary>A-130 reference & relevance</summary><p>'+e(x['reference_passage'])+'</p><p class="note">Extracted source passage; '+e(x['locator'])+'. A citation establishes a reference, not that this entire memorandum was caused by A-130.</p></details>'
 if matches:
  body+='<details><summary>Term flags: '+e(', '.join(m['term'] for m in matches))+'</summary>'
  for m in matches:body+=f'<div class="match"><b>{e(m["term"])} · {e(m["locator"])}</b><p>{e(m["passage"])}</p><small>{e(m["verification"])}</small></div>'
  body+='</details>'
 body+='<details><summary>Provenance & date precision</summary><p>'+e(x['date_precision'])+'</p><p>'+e(x.get('text_quality','See supporting record'))+'</p>'
 if x.get('sha256'):body+='<p>Retrieved 2026-10-10 · '+str(x['bytes'])+' bytes</p><code>'+x['sha256']+'</code>'
 body+='</details>'
 parts += [f'<article class="record" id="doc-{x["id"]}" data-type="{e(x["type"])}" data-era="{era}" data-relation="{e(x["relation"])}" data-terms="{e(tags)}" data-date="{x["date"]}" data-title="{e(x["title"])}">{body}</article>']
parts+=['</div></section><section id="method"><h2>What this collection can establish.</h2><div class="prose"><h3>Scope and method</h3><p>This is a historical research edition through October 10, 2026. Primary evidence comes from enacted laws on GovInfo, Federal Register originals, OMB and presidential archives, and NIST/NBS publications. The 1965 A-71 is a reproduction within a government-hosted FIPS compilation. Original PDFs and HTML are preserved with SHA-256 hashes. Extracted text is a convenience copy and may contain OCR or layout errors; it is not a reconstructed original.</p><p>The memorandum discovery pass searched six official index pages, deduplicated 721 numbered candidates, downloaded 717, and identified 89 direct A-130 matches in extracted text. Selected domain extensions and the 2011 unnumbered FedRAMP memorandum were then added. Searches of Federal Register records, archival circular listings and NIST publications supplemented that pass. The search log and candidate manifest make the boundaries auditable.</p><h3>Known limits</h3><ul><li>Standalone originals of the 1978 A-71 security transmittal and Bulletins 88-16 and 90-08 were not recovered. Later OMB primary evidence documents their role and supersession.</li><li>The original 2005 FIPS 201 download remains unresolved; the historical event is not labeled as a recovered file.</li><li>The memorandum scan covers the linked documents exposed by the six searched indexes. Missing links, unusual numbering, OCR errors, attachment-only references and unindexed material can escape it. It is not proof that every relevant memorandum has been found.</li><li>NIST coverage selects consequential editions across the requested domains. It does not reproduce every intermediate revision, erratum, withdrawal notice or publication in the 800 series.</li><li>Exact-term flags and related-terminology flags are separate. Extracted candidates are labeled; only passages explicitly marked reviewed have been manually checked. No hit does not prove absence in an unreliable scan.</li><li>Rescission and supersession are recorded only where documented. Historical inclusion does not establish present-day applicability.</li></ul><h3>Reading and reuse</h3><p>The complete narrative and evidence records are present in the HTML. JavaScript adds local filtering and event inspection; no network is needed to read downloaded content. Official-source links require the internet. Saved original HTML may contain its publisher’s remote asset references; it is retained as source material, while the report itself uses no external assets.</p><p><a href="manifest.json" download>Download source manifest (JSON)</a> · <a href="manifest.csv" download>Download source index (CSV)</a> · <a href="search-log.json">Searched collections</a> · <a href="candidate-manifest.json">Memorandum discovery results</a></p></div></section><footer><p>Independent historical research. Sources govern; the report is an analytical guide.</p><a href="#top">Return to the beginning ↑</a><button id="print">Print report</button></footer></main></body></html>']
(S/'manifest.json').write_text(json.dumps(records,indent=2));(S/'index.html').write_text(''.join(parts));(S/'.nojekyll').touch()
with (S/'manifest.csv').open('w') as f:
 keys=['id','date','date_precision','title','type','relation','status','url','local','sha256','availability'];w=csv.DictWriter(f,fieldnames=keys,extrasaction='ignore');w.writeheader();w.writerows(records)
for source,dest in [('search-log.json','search-log.json'),('memo-candidates.json','candidate-manifest.json')]: (S/dest).write_text((R/'data'/source).read_text())
